import sys

def find_lexicographically_smallest_word(grid):
    rows = len(grid)
    cols = len(grid[0])

    # Helper function to check if two cells are adjacent
    def are_adjacent(r1, c1, r2, c2):
        if abs(r1 - r2) <= 1 and abs(c1 - c2) <= 1:
            return True
        return False

    # Initialize the smallest word to 'ZZZ'
    smallest_word = 'ZZZ'

    # Iterate over all possible combinations of three different cells
    for r1 in range(rows):
        for c1 in range(cols):
            for r2 in range(rows):
                for c2 in range(cols):
                    if r1 == r2 and c1 == c2:
                        continue  # Skip the same cell
                    if are_adjacent(r1, c1, r2, c2):
                        for r3 in range(rows):
                            for c3 in range(cols):
                                if r3 == r1 or r3 == r2 or r3 == c1 or r3 == c2 or c3 == c1 or c3 == c2:
                                    continue  # Skip the same cell
                                if are_adjacent(r2, c2, r3, c3):
                                    # Check if the word is lexicographically smaller
                                    word = sorted([grid[r1][c1], grid[r2][c2], grid[r3][c3]])
                                    if word < smallest_word:
                                        smallest_word = ''.join(word)

    return smallest_word

