    # Function to check if two cells are adjacent
    def are_adjacent(r1, c1, r2, c2):
        return abs(r1 - r2) <= 1 and abs(c1 - c2) <= 1

    # Initialize the smallest word with a large value
    smallest_word = 'ZZZ'

