def min_operations(a, b):
    # Check if the pieces are already equal
    if a == b:
        return 0

    # Function to simulate the operations
    def simulate_operations(a, b):
        count = 0
        while a != b:
            if a > b:
                if a % 2 == 0:
                    a //= 2
                elif a % 3 == 0:
                    a //= 3
                elif a % 5 == 0:
                    a //= 5
                else:
                    return -1
            else:
                if b % 2 == 0:
                    b //= 2
                elif b % 3 == 0:
                    b //= 3
                elif b % 5 == 0:
                    b //= 5
                else:
                    return -1
            count += 1
        return count

    # Try both possible operations from a to b and vice versa
    return min(simulate_operations(a, b), simulate_operations(b, a))

